        self::assertSame($this->decoded('{"count":1,"next":null,"previous":null,"results":[{"uuid":"abcdef99-3456-4890-abcd-ef1234567890","transaction_number":4087,"txn_id":"your-txn-2026-10-02-017","transaction_type":"finance","action_type":"deposit","status":"APPROVED","source":"LIVE","direction":"INBOUND","amount":"250","currency":"EUR","currency_type":"fiat","preferred_currency_amount":"270.08","preferred_currency_code":"USD","payment_details":"Card top-up","txn_date":"2026-10-02T14:10:00Z","created_at":"2026-10-02T14:10:03.512244Z","score":12,"severity":"LOW","decision_reason_code":null,"decision_reason_label":null,"tags":[],"subject_name":"Maria Garcia","subject_vendor_data":"user-12345","subject_type":"user","subject_uuid":"e1111111-2222-4333-8444-555555555555","counterparty_name":null,"counterparty_vendor_data":null,"counterparty_country":null,"subject_country":"ESP","assigned_to_name":null,"travel_rule_status":null,"application_id":"aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee","application_name":"Production app","organization_id":"11111111-2222-3333-4444-555555555555","organization_name":"Example Org"}]}'), $result->toArray());
    }

    public function testGeneratePdf(): void
    {
        $this->queueBinary(200, 'binary-content', 'application/pdf');

        $result = $this->client->transactions->generatePdf('transactionUuid-1');

        $request = $this->lastRequest();
        self::assertSame('GET', $request->getMethod());
        self::assertSame('verification.didit.me', $request->getUri()->getHost());
        self::assertSame('/v3/organization/org-7f3a/application/app-91c2/transactions/transactionUuid-1/pdf/', $request->getUri()->getPath());
        self::assertSame([], $this->queryParams($request));
        self::assertSame(self::API_KEY, $request->getHeaderLine('x-api-key'));
        self::assertSame('application/pdf, application/json', $request->getHeaderLine('Accept'));
        self::assertSame('', (string) $request->getBody());
        self::assertSame('binary-content', $result->contents());
        self::assertSame('application/pdf', $result->contentType());
    }

    public function testBatchDelete(): void
    {
        $this->queueEmpty(204);

        $result = $this->client->transactions->batchDelete([
            'transaction_uuids' => [
                '3f2c8a7e-5b1d-4c9a-8e6f-2a1b3c4d5e6f',
            ],
            'delete_all' => true,
        ]);

        $request = $this->lastRequest();
        self::assertSame('DELETE', $request->getMethod());
        self::assertSame('verification.didit.me', $request->getUri()->getHost());
        self::assertSame('/v3/organization/org-7f3a/application/app-91c2/transactions/delete/', $request->getUri()->getPath());
        self::assertSame([], $this->queryParams($request));
        self::assertSame(self::API_KEY, $request->getHeaderLine('x-api-key'));
        self::assertSame('application/json', $request->getHeaderLine('Content-Type'));
        self::assertSame('{"transaction_uuids":["3f2c8a7e-5b1d-4c9a-8e6f-2a1b3c4d5e6f"],"delete_all":true}', $this->canonicalBody($request));
        self::assertSame(204, $result->rawResponse()?->status);
    }
